const { put, get } = require('./store.cjs');
const [file, action, id, value] = process.argv.slice(2);
if (!file || !id || !['put', 'get'].includes(action)) { console.error('Invalid command'); process.exit(2); }
if (action === 'put') {
  if (!/^[0-5]$/.test(value ?? '')) { console.error('Priority must be 0 through 5'); process.exit(2); }
  put(file, id, Number(value));
  console.log(JSON.stringify({ saved: true }));
} else {
  console.log(JSON.stringify(get(file, id)));
}

